/** Example 1 (section 1.1): the StockQuote service, SOAP 1.1 over HTTP, document style. */
export const EXAMPLE_1_STOCK_QUOTE = "<?xml version=\"1.0\"?>\n<definitions name=\"StockQuote\"\n\ntargetNamespace=\"http://example.com/stockquote.wsdl\"\n          xmlns:tns=\"http://example.com/stockquote.wsdl\"\n          xmlns:xsd1=\"http://example.com/stockquote.xsd\"\n          xmlns:soap=\"http://schemas.xmlsoap.org/wsdl/soap/\"\n          xmlns=\"http://schemas.xmlsoap.org/wsdl/\">\n\n    <types>\n       <schema targetNamespace=\"http://example.com/stockquote.xsd\"\n              xmlns=\"http://www.w3.org/2000/10/XMLSchema\">\n           <element name=\"TradePriceRequest\">\n              <complexType>\n                  <all>\n                      <element name=\"tickerSymbol\" type=\"string\"/>\n                  </all>\n              </complexType>\n           </element>\n           <element name=\"TradePrice\">\n              <complexType>\n                  <all>\n                      <element name=\"price\" type=\"float\"/>\n                  </all>\n              </complexType>\n           </element>\n       </schema>\n    </types>\n\n    <message name=\"GetLastTradePriceInput\">\n        <part name=\"body\" element=\"xsd1:TradePriceRequest\"/>\n    </message>\n\n    <message name=\"GetLastTradePriceOutput\">\n        <part name=\"body\" element=\"xsd1:TradePrice\"/>\n    </message>\n\n    <portType name=\"StockQuotePortType\">\n        <operation name=\"GetLastTradePrice\">\n           <input message=\"tns:GetLastTradePriceInput\"/>\n           <output message=\"tns:GetLastTradePriceOutput\"/>\n        </operation>\n    </portType>\n\n    <binding name=\"StockQuoteSoapBinding\" type=\"tns:StockQuotePortType\">\n        <soap:binding style=\"document\" transport=\"http://schemas.xmlsoap.org/soap/http\"/>\n        <operation name=\"GetLastTradePrice\">\n           <soap:operation soapAction=\"http://example.com/GetLastTradePrice\"/>\n           <input>\n               <soap:body use=\"literal\"/>\n           </input>\n           <output>\n               <soap:body use=\"literal\"/>\n           </output>\n        </operation>\n    </binding>\n\n    <service name=\"StockQuoteService\">\n        <documentation>My first service</documentation>\n        <port name=\"StockQuotePort\" binding=\"tns:StockQuoteBinding\">\n           <soap:address location=\"http://example.com/stockquote\"/>\n        </port>\n    </service>\n\n</definitions>";

/** Example 2 (section 2.1.2), document 1 of 3: stockquote.xsd, the data types. */
export const EXAMPLE_2_SCHEMA = "<?xml version=\"1.0\"?>\n<schema targetNamespace=\"http://example.com/stockquote/schemas\"\n       xmlns=\"http://www.w3.org/2000/10/XMLSchema\">\n       \n    <element name=\"TradePriceRequest\">\n        <complexType>\n            <all>\n                <element name=\"tickerSymbol\" type=\"string\"/>\n            </all>\n        </complexType>\n    </element>\n    <element name=\"TradePrice\">\n        <complexType>\n            <all>\n                <element name=\"price\" type=\"float\"/>\n            </all>\n        </complexType>\n    </element>\n</schema>";

/** Example 2, document 2 of 3: stockquote.wsdl, the abstract definitions (it imports document 1). */
export const EXAMPLE_2_DEFINITIONS = "<?xml version=\"1.0\"?>\n<definitions name=\"StockQuote\"\n\ntargetNamespace=\"http://example.com/stockquote/definitions\"\n          xmlns:tns=\"http://example.com/stockquote/definitions\"\n          xmlns:xsd1=\"http://example.com/stockquote/schemas\"\n          xmlns:soap=\"http://schemas.xmlsoap.org/wsdl/soap/\"\n          xmlns=\"http://schemas.xmlsoap.org/wsdl/\">\n\n   <import namespace=\"http://example.com/stockquote/schemas\"\n           location=\"http://example.com/stockquote/stockquote.xsd\"/>\n\n    <message name=\"GetLastTradePriceInput\">\n        <part name=\"body\" element=\"xsd1:TradePriceRequest\"/>\n    </message>\n\n    <message name=\"GetLastTradePriceOutput\">\n        <part name=\"body\" element=\"xsd1:TradePrice\"/>\n    </message>\n\n    <portType name=\"StockQuotePortType\">\n        <operation name=\"GetLastTradePrice\">\n           <input message=\"tns:GetLastTradePriceInput\"/>\n           <output message=\"tns:GetLastTradePriceOutput\"/>\n        </operation>\n    </portType>\n</definitions>";

/** Example 2, document 3 of 3: stockquoteservice.wsdl, the binding and service (it imports document 2). */
export const EXAMPLE_2_SERVICE = "<?xml version=\"1.0\"?>\n<definitions name=\"StockQuote\"\n\ntargetNamespace=\"http://example.com/stockquote/service\"\n          xmlns:tns=\"http://example.com/stockquote/service\"\n          xmlns:soap=\"http://schemas.xmlsoap.org/wsdl/soap/\"\n          xmlns:defs=\"http://example.com/stockquote/definitions\"\n          xmlns=\"http://schemas.xmlsoap.org/wsdl/\">\n\n   <import namespace=\"http://example.com/stockquote/definitions\"\n           location=\"http://example.com/stockquote/stockquote.wsdl\"/>\n\n    <binding name=\"StockQuoteSoapBinding\" type=\"defs:StockQuotePortType\">\n        <soap:binding style=\"document\" transport=\"http://schemas.xmlsoap.org/soap/http\"/>\n        <operation name=\"GetLastTradePrice\">\n           <soap:operation soapAction=\"http://example.com/GetLastTradePrice\"/>\n           <input>\n               <soap:body use=\"literal\"/>\n           </input>\n           <output>\n               <soap:body use=\"literal\"/>\n           </output>\n        </operation>\n    </binding>\n\n    <service name=\"StockQuoteService\">\n        <documentation>My first service</documentation>\n        <port name=\"StockQuotePort\" binding=\"tns:StockQuoteBinding\">\n           <soap:address location=\"http://example.com/stockquote\"/>\n        </port>\n    </service>\n</definitions>";

/** Example 3 (section 3.1): a one-way operation over SMTP with a SOAP header. */
export const EXAMPLE_3_SMTP_HEADER = "<?xml version=\"1.0\"?>\n<definitions name=\"StockQuote\"\n          targetNamespace=\"http://example.com/stockquote.wsdl\"\n          xmlns:tns=\"http://example.com/stockquote.wsdl\"\n          xmlns:xsd1=\"http://example.com/stockquote.xsd\"\n          xmlns:soap=\"http://schemas.xmlsoap.org/wsdl/soap/\"\n          xmlns=\"http://schemas.xmlsoap.org/wsdl/\">\n\n    <message name=\"SubscribeToQuotes\">\n        <part name=\"body\" element=\"xsd1:SubscribeToQuotes\"/>\n        <part name=\"subscribeheader\" element=\"xsd1:SubscriptionHeader\"/>\n    </message>\n\n    <portType name=\"StockQuotePortType\">\n        <operation name=\"SubscribeToQuotes\">\n           <input message=\"tns:SubscribeToQuotes\"/>\n        </operation>\n    </portType>\n\n    <binding name=\"StockQuoteSoap\" type=\"tns:StockQuotePortType\">\n        <soap:binding style=\"document\" transport=\"http://example.com/smtp\"/>\n        <operation name=\"SubscribeToQuotes\">\n           <input message=\"tns:SubscribeToQuotes\">\n               <soap:body parts=\"body\" use=\"literal\"/>\n               <soap:header message=\"tns:SubscribeToQuotes\" part=\"subscribeheader\" use=\"literal\"/>\n           </input>\n        </operation>\n    </binding>\n\n    <service name=\"StockQuoteService\">\n        <port name=\"StockQuotePort\" binding=\"tns:StockQuoteSoap\">\n           <soap:address location=\"mailto:subscribe@example.com\"/>\n        </port>\n    </service>\n\n    <types>\n        <schema targetNamespace=\"http://example.com/stockquote.xsd\"\n               xmlns=\"http://www.w3.org/2000/10/XMLSchema\">\n           <element name=\"SubscribeToQuotes\">\n               <complexType>\n                   <all>\n                       <element name=\"tickerSymbol\" type=\"string\"/>\n                   </all>\n               </complexType>\n           </element>\n           <element name=\"SubscriptionHeader\" type=\"uriReference\"/>\n        </schema>\n    </types>\n</definitions>";

/** Example 4 (section 3.1): request-response RPC over HTTP, use="encoded". */
export const EXAMPLE_4_RPC_ENCODED = "<?xml version=\"1.0\"?>\n<definitions name=\"StockQuote\"\n          targetNamespace=\"http://example.com/stockquote.wsdl\"\n          xmlns:tns=\"http://example.com/stockquote.wsdl\"\n          xmlns:xsd=\"http://www.w3.org/2000/10/XMLSchema\"\n          xmlns:xsd1=\"http://example.com/stockquote.xsd\"\n          xmlns:soap=\"http://schemas.xmlsoap.org/wsdl/soap/\"\n          xmlns=\"http://schemas.xmlsoap.org/wsdl/\">\n\n    <message name=\"GetTradePriceInput\">\n        <part name=\"tickerSymbol\" element=\"xsd:string\"/>\n        <part name=\"time\" element=\"xsd:timeInstant\"/>\n    </message>\n\n    <message name=\"GetTradePriceOutput\">\n        <part name=\"result\" type=\"xsd:float\"/>\n    </message>\n\n    <portType name=\"StockQuotePortType\">\n        <operation name=\"GetTradePrice\">\n           <input message=\"tns:GetTradePriceInput\"/>\n           <output message=\"tns:GetTradePriceOutput\"/>\n        </operation>\n    </portType>\n\n    <binding name=\"StockQuoteSoapBinding\" type=\"tns:StockQuotePortType\">\n        <soap:binding style=\"rpc\" transport=\"http://schemas.xmlsoap.org/soap/http\"/>\n        <operation name=\"GetTradePrice\">\n           <soap:operation soapAction=\"http://example.com/GetTradePrice\"/>\n           <input>\n               <soap:body use=\"encoded\" namespace=\"http://example.com/stockquote\"\n                          encodingStyle=\"http://schemas.xmlsoap.org/soap/encoding/\"/>\n           </input>\n           <output>\n               <soap:body use=\"encoded\" namespace=\"http://example.com/stockquote\"\n                          encodingStyle=\"http://schemas.xmlsoap.org/soap/encoding/\"/>\n           </output>\n        </operation>>\n    </binding>\n\n    <service name=\"StockQuoteService\">\n        <documentation>My first service</documentation>\n        <port name=\"StockQuotePort\" binding=\"tns:StockQuoteBinding\">\n           <soap:address location=\"http://example.com/stockquote\"/>\n        </port>\n    </service>\n</definitions>";

/** Example 5 (section 3.1): RPC with an array type; the note leaves the prefix wsdl undeclared. */
export const EXAMPLE_5_RPC_ARRAYS = "<?xml version=\"1.0\"?>\n<definitions name=\"StockQuote\"\n\ntargetNamespace=\"http://example.com/stockquote.wsdl\"\n          xmlns:tns=\"http://example.com/stockquote.wsdl\"\n          xmlns:xsd=\"http://www.w3.org/2000/10/XMLSchema\"\n          xmlns:xsd1=\"http://example.com/stockquote/schema\"\n          xmlns:soap=\"http://schemas.xmlsoap.org/wsdl/soap/\"\n          xmlns:soapenc=\"http://schemas.xmlsoap.org/soap/encoding/\"\n          xmlns=\"http://schemas.xmlsoap.org/wsdl/\">\n\n    <types>\n       <schema targetNamespace=\"http://example.com/stockquote/schema\"\n              xmlns=\"http://www.w3.org/2000/10/XMLSchema\">\n           <complexType name=\"TimePeriod\">\n              <all>\n                  <element name=\"startTime\" type=\"xsd:timeInstant\"/>\n                  <element name=\"endTime\" type=\"xsd:timeInstant\"/>\n              </all>\n           </complexType>\n           <complexType name=\"ArrayOfFloat\">\n              <complexContent>\n                  <restriction base=\"soapenc:Array\">\n                      <attribute ref=\"soapenc:arrayType\" wsdl:arrayType=\"xsd:float[]\"/>\n                  </restriction>\n              </complexContent>\n           </complexType>\n       </schema>\n    </types>\n\n    <message name=\"GetTradePricesInput\">\n        <part name=\"tickerSymbol\" element=\"xsd:string\"/>\n        <part name=\"timePeriod\" element=\"xsd1:TimePeriod\"/>\n    </message>\n\n    <message name=\"GetTradePricesOutput\">\n        <part name=\"result\" type=\"xsd1:ArrayOfFloat\"/>\n        <part name=\"frequency\" type=\"xsd:float\"/>\n    </message>\n\n    <portType name=\"StockQuotePortType\">\n        <operation name=\"GetLastTradePrice\" parameterOrder=\"tickerSymbol timePeriod frequency\">\n           <input message=\"tns:GetTradePricesInput\"/>\n           <output message=\"tns:GetTradePricesOutput\"/>\n        </operation>\n    </portType>\n\n    <binding name=\"StockQuoteSoapBinding\" type=\"tns:StockQuotePortType\">\n        <soap:binding style=\"rpc\" transport=\"http://schemas.xmlsoap.org/soap/http\"/>\n        <operation name=\"GetTradePrices\">\n           <soap:operation soapAction=\"http://example.com/GetTradePrices\"/>\n           <input>\n               <soap:body use=\"encoded\" namespace=\"http://example.com/stockquote\"\n                          encodingStyle=\"http://schemas.xmlsoap.org/soap/encoding/\"/>\n           </input>\n           <output>\n               <soap:body use=\"encoded\" namespace=\"http://example.com/stockquote\"\n                          encodingStyle=\"http://schemas.xmlsoap.org/soap/encoding/\"/>\n           </output>\n        </operation>>\n    </binding>\n\n    <service name=\"StockQuoteService\">\n        <documentation>My first service</documentation>\n        <port name=\"StockQuotePort\" binding=\"tns:StockQuoteBinding\">\n           <soap:address location=\"http://example.com/stockquote\"/>\n        </port>\n    </service>\n</definitions>";
